var renderer=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).First(r=>r.name=="PlantHolder");var material=renderer.sharedMaterial;return new{name=renderer.name,mesh=renderer.GetComponent<UnityEngine.MeshFilter>().sharedMesh.name,size=renderer.bounds.size.ToString(),material=material.name,shader=material.shader.name,texture=material.GetTexture("_BaseMap")?.name,normal=material.GetTexture("_BumpMap")?.name,keywords=material.shaderKeywords};
